  const document = {
    version: 1,
    preferences: {
      mode: "manual",
      nested: { pages: [1, 2] },
    },
    ignored: true,
    links: [
      {
        key: "v2",
        href: "",
        caption: "",
        memo: "",
        folder: "work",
        tags: [],
        ignored: "link extra",
      },
      {
        key: "home-id",
        href: "https://home.test",
        caption: "Home",
        memo: null,
        folder: "home",
        tags: ["first", "second"],
      },
      {
